// Get the text returned by the OpenAI Message a Model node.
const rawText =
  $json.output?.[0]?.content?.find(
    (item) => item.type === 'output_text'
  )?.text ?? null;

// Recover the original normalized lead/envelope.
// The OpenAI node's output does not automatically preserve it.
const original = $('Valid Lead?').item.json;

const validationErrors = [];
let analysis = null;

// 1. Make sure OpenAI actually returned text.
if (!rawText) {
  validationErrors.push('AI response contained no output text');
}

// 2. Parse the JSON.
if (rawText) {
  try {
    analysis = JSON.parse(rawText);
  } catch (error) {
    validationErrors.push(
      `AI response was not valid JSON: ${error.message}`
    );
  }
}

// 3. Validate the parsed structure.
if (analysis) {
  const allowedCustomerTypes = [
    'commercial',
    'residential',
    'unknown',
  ];

  const allowedServices = [
    'commercial_cleaning',
    'residential_cleaning',
    'other',
    'unknown',
  ];

  const allowedIntents = [
    'request_quote',
    'information_gathering',
    'immediate_service',
    'other',
    'unknown',
  ];

  const allowedTimelines = [
    'immediate',
    'within_30_days',
    'within_90_days',
    'later',
    'unknown',
  ];

  if (!allowedCustomerTypes.includes(analysis.customer_type)) {
    validationErrors.push('Invalid customer_type');
  }

  if (!allowedServices.includes(analysis.service)) {
    validationErrors.push('Invalid service');
  }

  if (!allowedIntents.includes(analysis.intent)) {
    validationErrors.push('Invalid intent');
  }

  if (!allowedTimelines.includes(analysis.timeline)) {
    validationErrors.push('Invalid timeline');
  }

  if (
    analysis.location !== null &&
    typeof analysis.location !== 'string'
  ) {
    validationErrors.push('location must be a string or null');
  }

  if (
    analysis.facility_count !== null &&
    typeof analysis.facility_count !== 'number'
  ) {
    validationErrors.push(
      'facility_count must be a number or null'
    );
  }

  if (
    analysis.recurring_service !== null &&
    typeof analysis.recurring_service !== 'boolean'
  ) {
    validationErrors.push(
      'recurring_service must be a boolean or null'
    );
  }

  if (
    typeof analysis.confidence !== 'number' ||
    analysis.confidence < 0 ||
    analysis.confidence > 1
  ) {
    validationErrors.push(
      'confidence must be a number between 0 and 1'
    );
  }

  if (typeof analysis.reasoning_summary !== 'string') {
    validationErrors.push(
      'reasoning_summary must be a string'
    );
  }
}

// Return the original lead plus the structured AI analysis.
return {
  ...original,

  ai_analysis: analysis,

  ai_validation: {
    valid: validationErrors.length === 0,
    errors: validationErrors,
  },

  raw_ai_output: rawText,
};

const analysis = $json.ai_analysis;
const aiValid = $json.ai_validation?.valid === true;

let qualification = 'HUMAN_REVIEW';
let qualificationReason = 'Unable to determine qualification automatically';

// 1. Invalid or malformed AI output always requires review.
if (!aiValid || !analysis) {
  qualification = 'HUMAN_REVIEW';
  qualificationReason = 'AI analysis failed validation';
}

// 2. Low-confidence AI result requires human review.
else if (analysis.confidence < 0.75) {
  qualification = 'HUMAN_REVIEW';
  qualificationReason = 'AI confidence below 0.75 threshold';
}

// 3. Explicit residential requests are not qualified.
else if (
  analysis.customer_type === 'residential' ||
  analysis.service === 'residential_cleaning'
) {
  qualification = 'NOT_QUALIFIED';
  qualificationReason = 'Business provides commercial cleaning only';
}

// 4. Strong commercial quote opportunity.
else if (
  analysis.customer_type === 'commercial' &&
  analysis.service === 'commercial_cleaning' &&
  analysis.intent === 'request_quote' &&
  (
    analysis.timeline === 'immediate' ||
    analysis.timeline === 'within_30_days' ||
    analysis.timeline === 'within_90_days'
  )
) {
  qualification = 'HIGH_PRIORITY';
  qualificationReason = 'Qualified commercial quote opportunity';
}

// 5. Everything else gets human review.
else {
  qualification = 'HUMAN_REVIEW';
  qualificationReason =
    'Lead is not clearly qualified or disqualified by deterministic rules';
}

return {
  ...$json,

  qualification: {
    status: qualification,
    reason: qualificationReason,
    evaluated_at: new Date().toISOString(),
  },
};

